    std::vector<Point2d> sortedPoints = points;
    std::sort(sortedPoints.begin(), sortedPoints.end());

    if (sortedPoints.front() == sortedPoints.back()) {
        result.push_back(sortedPoints.front());
        return result;
    }

    std::vector<Point2d> hull;
    std::vector<Point2d> lowerHull;
    std::vector<Point2d> upperHull;

    // Lower hull
    for (const auto& p : sortedPoints) {
        while (lowerHull.size() >= 2 && 
               !cg3::isPointAtRight(lowerHull[lowerHull.size()-2], 
                                   lowerHull[lowerHull.size()-1], p)) {
            lowerHull.pop_back();
        }
        lowerHull.push_back(p);
    }

    // Upper hull
    for (auto it = sortedPoints.rbegin(); it != sortedPoints.rend(); ++it) {
        const auto& p = *it;
        while (upperHull.size() >= 2 && 
               !cg3::isPointAtRight(upperHull[upperHull.size()-2], 
                                   upperHull[upperHull.size()-1], p)) {
            upperHull.pop_back();
        }
        upperHull.push_back(p);
    }

    // Combine lower and upper hulls (remove duplicates at endpoints)
    for (size_t i = 0; i < lowerHull.size() - 1; ++i) {
        hull.push_back(lowerHull[i]);
    }
    for (size_t i = 0; i < upperHull.size() - 1; ++i) {
        hull.push_back(upperHull[i]);
    }

    return hull;

